import {CATEGORIES,STATUSES,AGENCIES,LOCATIONS,AREAS,routeReport,findDuplicates,clusterAlerts,makeSeed,createSubmission,validCoordinates} from './core.js';
import {requestLocation} from './location.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='civic-relay-v1',OWNER='civic-relay-owner';
let storageProblem='';
let state;try{const raw=localStorage.getItem(STORE);const data=raw?JSON.parse(raw):makeSeed();if(data.version!==1||!Array.isArray(data.incidents)||data.incidents.some(i=>!i.id||!i.route||!Array.isArray(i.reports)||!Array.isArray(i.history)))throw Error();state=data;}catch{state=makeSeed();storageProblem='Saved data could not be loaded. Sample reports are shown; export any important records before resetting.';}
let owner;try{owner=localStorage.getItem(OWNER)||crypto.randomUUID();localStorage.setItem(OWNER,owner);}catch{owner=crypto.randomUUID();storageProblem='Browser storage is unavailable. Submission will report an error until storage is enabled.';}
let view=['agency','routing'].includes(location.hash.slice(1))?location.hash.slice(1):'resident';
let screen='home',step=1,successId=null,reportTab='mine',busy=false;
let filters={search:'',agency:'all',status:'all'};
let cancelGpsRequest=null;
let gpsFeedback={status:'idle',message:''};
const blank=()=>({category:'',description:'',photo:null,lat:null,lng:null,location:'',duplicate:null});let draft=blank();
const date=t=>new Date(t).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const shortDate=t=>new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const symbol=c=>({water:'≈',road:'⌁',lighting:'☼',other:'◇'}[c]||'◇');
const statusClass=s=>s.toLowerCase().replaceAll(' ','-');
const statusBadge=s=>`<span class="status ${statusClass(s)}">${esc(s)}</span>`;
function toast(message){const el=$('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4500);}
function persist(next){try{localStorage.setItem(STORE,JSON.stringify(next));state=next;return true;}catch{toast('Could not save. Browser storage may be full or disabled. Try a smaller photo or export your reports.');return false;}}
function error(message){const el=$('#form-error');if(el){el.textContent=message;el.setAttribute('role','alert');}else toast(message);}
function routeCard(route){return `<div class="routing-result ${route.agency?'':'pending'}"><span class="small">${route.agency?'MATCHED IN DEMO':'ROUTING REVIEW'}</span><strong>${esc(route.agency||'Manual review queue')}</strong><div>${esc(route.area||'Outside demo coverage')}${route.district?' · '+esc(route.district):''}</div><div class="route-line">${esc(route.reason)}</div><span class="small">Demo queue only · No external delivery</span></div>`;}
function streetArt(){return `<div class="hero-art"><svg viewBox="0 0 320 160" role="img" aria-label="Illustration of a neighborhood street"><rect width="320" height="160" fill="#e8edde"/><path d="M0 113L320 80V160H0Z" fill="#d2dbca"/><path d="M0 135L320 102" stroke="#f6f8ed" stroke-width="3" stroke-dasharray="29 22"/><path d="M22 113V55L56 35L90 55V105" fill="#f9faf0"/><path d="M17 58L56 32L95 57" fill="none" stroke="#8ea778" stroke-width="6"/><path d="M41 110V77H62V108" fill="#a0b786"/><path d="M73 65H84V80H73" fill="#c2d0ae"/><path d="M146 100V43L175 23L205 43V94" fill="#c4d2ad"/><path d="M140 45L175 20L211 43" fill="none" stroke="#74905e" stroke-width="6"/><path d="M164 98V68H183V96" fill="#f9faf0"/><path d="M154 49H164V60H154M184 49H194V60H184" fill="none" stroke="#f9faf0" stroke-width="5"/><path d="M248 88V46" stroke="#7d966b" stroke-width="5"/><circle cx="248" cy="33" r="24" fill="#9db784"/><circle cx="262" cy="42" r="17" fill="#adc393"/><path d="M112 100V64Q112 54 123 54H129" fill="none" stroke="#6f8565" stroke-width="3"/><ellipse cx="184" cy="132" rx="22" ry="6" fill="#a5b899"/><path d="M179 122V111M185 121V109M191 122V112" stroke="#769766" stroke-width="2"/></svg><span>A BETTER BLOCK STARTS WITH YOU</span></div>`;}
function mini(i){return `<button class="report-mini" data-detail="${esc(i.id)}"><span class="category-icon ${esc(i.category)}">${symbol(i.category)}</span><span><strong>${esc(i.title)}</strong><small>${esc(i.id)} · ${esc(i.status)} · ${shortDate(i.created)}</small></span><span class="chevron">›</span></button>`;}
function phoneShell(content){return `<div class="phone"><div class="phone-status"><span>9:41</span><span class="phone-island"></span><span class="signals">▮▮ ▰</span></div><div class="phone-header"><span class="phone-wordmark">civicrelay<span style="color:#89a660"> ↗</span></span><span class="avatar">YOU</span></div><div class="phone-content" id="phone-screen">${content}</div><nav class="phone-nav" aria-label="Resident navigation"><button data-screen="home" class="${screen==='home'?'selected':''}"><i>⌂</i>Home</button><button data-screen="new" class="${screen==='new'?'selected':''}"><i>⊕</i>Report</button><button data-screen="reports" class="${screen==='reports'?'selected':''}"><i>▤</i>My reports</button></nav><div class="home-bar"></div></div>`;}
function resident(){let content='';
 if(screen==='home'){
 const mine=state.incidents.filter(i=>i.reports.some(r=>r.owner===owner));const list=mine.length?mine:state.incidents.slice(0,2);
 content=`<div class="location-label">⌖ Your neighborhood, connected</div><h2>A little action.<br>A better neighborhood.</h2><p>Spot an issue? Help it reach the right people.</p>${streetArt()}<button class="primary block" data-action="start"><span>＋</span> Report an issue <span style="margin-left:auto">↗</span></button><div class="phone-hint">About a minute · No account needed for demo</div><div class="section-label">${mine.length?'Your latest reports':'Around the neighborhood'}<button class="text-button" data-screen="reports">View all</button></div>${list.map(mini).join('')}${!mine.length?'<p class="phone-hint">Sample incidents · Submit one to start your history</p>':''}`;
 }else if(screen==='new'){
 content=`<button class="back" data-action="back">← ${step===1?'Back to home':'Previous step'}</button><div class="wizard-progress" aria-label="Step ${step} of 3">${[1,2,3].map(n=>`<span class="${n<=step?'on':''}"></span>`).join('')}</div><div class="overline">${step===1?'01 / THE ISSUE':step===2?'02 / THE LOCATION':'03 / REVIEW & ROUTE'}</div>`;
 if(step===1)content+=`<h2>What needs a little attention?</h2><p class="form-intro">Choose a category and tell us what you see.</p><label>Issue category</label><div class="category-grid">${Object.entries(CATEGORIES).map(([c,name])=>`<button class="category-choice ${draft.category===c?'selected':''}" data-category="${c}" aria-pressed="${draft.category===c}"><span>${symbol(c)}</span>${name}</button>`).join('')}</div>${draft.photo?`<div class="form-field"><img src="${draft.photo}" class="photo-preview" alt="Your uploaded evidence"><div class="photo-actions"><span>Photo attached</span><button data-action="remove-photo">Remove</button></div></div>`:`<label class="photo-upload"><span class="photo-icon">⊞</span><strong>${busy?'Preparing photo…':'Take a photo or upload'}</strong><p>Optional · JPEG, PNG or WebP · Up to 10 MB</p><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Take a photo or upload evidence" ${busy?'disabled':''}></label>`}<div class="form-field"><label for="description">What did you notice?</label><textarea id="description" maxlength="1200" placeholder="For example: water is pooling beside a pipe near the sidewalk.">${esc(draft.description)}</textarea></div><p class="phone-hint">Choose the category yourself. Image recognition comes later.</p><div id="form-error" class="error"></div><div class="form-actions"><button class="primary block" data-action="next" ${busy?'disabled':''}>Continue to location →</button></div>`;
 if(step===2)content+=`<h2>Where is the issue?</h2><p class="form-intro">Use a sample location, your current location, or enter coordinates.</p>${gpsControls()}<div class="sample-locations">${LOCATIONS.map((l,n)=>`<button class="sample-location ${draft.lat===l.lat&&draft.lng===l.lng?'selected':''}" data-location="${n}"><span>⌖</span><span><strong>${l.name}</strong><small>${l.label}</small></span><span style="margin-left:auto">${draft.lat===l.lat&&draft.lng===l.lng?'✓':'›'}</span></button>`).join('')}</div><div class="coords"><div><label for="lat">Latitude</label><input id="lat" type="number" step="any" min="-90" max="90" value="${draft.lat??''}" placeholder="37.326"></div><div><label for="lng">Longitude</label><input id="lng" type="number" step="any" min="-180" max="180" value="${draft.lng??''}" placeholder="-121.910"></div></div><p class="phone-hint">For an uploaded photo, choose where the issue was photographed.</p><div id="form-error" class="error"></div><div class="form-actions"><button class="primary block" data-action="next">Review report →</button></div>`;
 if(step===3){const route=routeReport(draft.category,draft.lat,draft.lng),duplicates=findDuplicates(state.incidents,draft);content+=`<h2>Ready for the right desk.</h2><p class="form-intro">Check your report before adding it to the demo queue.</p>${draft.photo?`<img class="photo-preview" src="${draft.photo}" alt="Report photo">`:''}<div class="review-summary"><p><strong>${esc(CATEGORIES[draft.category])}</strong></p><p>${esc(draft.description)}</p><span class="muted">⌖ ${draft.lat.toFixed(5)}, ${draft.lng.toFixed(5)}</span></div>${routeCard(route)}${duplicates.length?`<div class="duplicate-box"><p><strong>A nearby report may describe this issue.</strong> Same category, within 60 meters. Please confirm.</p>${duplicates.map(i=>`<label><input type="radio" name="duplicate" value="${esc(i.id)}" ${draft.duplicate===i.id?'checked':''}><span>Add evidence to ${esc(i.id)}<br>${esc(i.title)}</span></label>`).join('')}<label><input type="radio" name="duplicate" value="" ${!draft.duplicate?'checked':''}><span>This is a separate issue</span></label></div>`:''}<div id="form-error" class="error"></div><div class="form-actions"><button class="primary block" data-action="submit">${draft.duplicate?'Add supporting report':'Submit demo report'} ↗</button></div><p class="phone-hint">Saved locally. No message is sent to an agency.</p>`;}
 }else if(screen==='success'){
 const i=state.incidents.find(i=>i.id===successId);content=`<div class="success"><div class="success-icon">✓</div><span class="overline">EVERY REPORT COUNTS</span><h2>Your neighborhood<br>thanks you.</h2><p class="form-intro">Your report is saved in this browser's demo queue.</p><div class="ticket"><span>REPORT REFERENCE</span><strong>${esc(i.id)}</strong>${esc(i.route.agency||'Manual review queue')}<br>${statusBadge(i.status)}</div><button class="primary block" data-detail="${esc(i.id)}">Track this report →</button><button class="ghost block" data-screen="home">Back to home</button><p class="phone-hint">Switch to Agency desk to see and manage your report.</p></div>`;
 }else{
 const list=reportTab==='mine'?state.incidents.filter(i=>i.reports.some(r=>r.owner===owner)):state.incidents;
 content=`<span class="overline">YOUR NEIGHBORHOOD</span><h2>Follow the progress.</h2><p>Every report has a place to go.</p><div class="section-tabs"><button data-report-tab="mine" class="${reportTab==='mine'?'on':''}">My reports</button><button data-report-tab="all" class="${reportTab==='all'?'on':''}">All demo incidents</button></div>${list.length?list.map(mini).join(''):'<div class="empty">Your reports will appear here.<br>Spot something? Start your first report.</div>'}<button class="primary block" style="margin-top:18px" data-action="start">＋ Report an issue</button>`;
 }
 return `<section class="resident-layout"><div class="intro"><div class="eyebrow">GOOD NEIGHBORS. BETTER NEIGHBORHOODS.</div><h1>See something. <br>Say something. <br><em>Change something.</em></h1><p>A photo, a location, a little care. Connect the issues on your block to the people who can help.</p><div class="intro-steps"><div class="intro-step"><span class="step-number">01</span><div><strong>Make it visible</strong><p>Capture the issue and add a few details.</p></div></div><div class="intro-step"><span class="step-number">02</span><div><strong>Find the right people</strong><p>Location and issue type find the right desk.</p></div></div><div class="intro-step"><span class="step-number">03</span><div><strong>Keep the conversation going</strong><p>Follow updates from the agency dashboard.</p></div></div></div><div class="intro-note"><span class="note-icon">↗</span><span>Try the resident app, then switch to Agency desk.<br>Your report connects both sides.</span></div></div>${phoneShell(content)}</section>`;
}
function filtered(){const q=filters.search.trim().toLowerCase();return state.incidents.filter(i=>(filters.agency==='all'||(filters.agency==='manual'?!i.route.agency:i.route.agency===filters.agency))&&(filters.status==='all'||i.status===filters.status)&&(!q||[i.title,i.id,i.route.agency,i.route.district,CATEGORIES[i.category]].some(v=>v?.toLowerCase().includes(q))));}
function tableRows(){const list=filtered();return list.length?list.map(i=>`<tr><td><button class="title-link" data-detail="${esc(i.id)}">${esc(i.title)}</button><div class="subline">${esc(i.id)} · ${esc(CATEGORIES[i.category])} · ${i.reports.length} report${i.reports.length===1?'':'s'}</div></td><td>${esc(i.route.agency||'Manual review')}<div class="subline">${esc(i.route.district||'Outside coverage')}</div></td><td>${statusBadge(i.status)}</td><td>${shortDate(i.created)}</td></tr>`).join(''):`<tr><td colspan="4"><div class="empty">No incidents match these filters.</div></td></tr>`;}
function agency(){const alerts=clusterAlerts(state.incidents);const open=state.incidents.filter(i=>i.status!=='Resolved');return `<section><div class="page-title"><div><span class="overline">THE AGENCY DESK</span><h1>A clearer picture of your community.</h1><p>One shared queue. Every issue accounted for. All departments shown in this demo.</p></div><div class="page-actions"><button class="secondary" data-action="export">↓ Export records</button><button class="primary" data-view="resident">＋ Resident report</button></div></div><div class="metrics"><div class="metric"><div class="metric-top">Open incidents <span>↗</span></div><strong>${open.length}</strong><p>Distinct unresolved issues</p></div><div class="metric"><div class="metric-top">In progress <span>◷</span></div><strong>${state.incidents.filter(i=>i.status==='In progress').length}</strong><p>Work underway in the demo</p></div><div class="metric"><div class="metric-top">Routing review <span>◇</span></div><strong>${open.filter(i=>!i.route.agency).length}</strong><p>Department needs verification</p></div><div class="metric"><div class="metric-top">Resolved <span>✓</span></div><strong>${state.incidents.filter(i=>i.status==='Resolved').length}</strong><p>Marked complete in this browser</p></div></div><div class="desk-grid"><section class="panel"><div class="panel-head"><h2>Incident queue</h2><span class="pill">Browser-local demo</span></div><div class="filters"><input id="search" type="search" placeholder="Search issues, references…" aria-label="Search incidents" value="${esc(filters.search)}"><select id="filter-agency" aria-label="Filter department"><option value="all">All departments</option>${Object.values(AGENCIES).map(a=>`<option ${filters.agency===a?'selected':''}>${esc(a)}</option>`).join('')}<option value="manual" ${filters.agency==='manual'?'selected':''}>Manual review</option></select><select id="filter-status" aria-label="Filter status"><option value="all">All statuses</option>${STATUSES.map(s=>`<option ${filters.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="table-wrap"><table class="report-table"><thead><tr><th scope="col">Incident</th><th scope="col">Assigned department</th><th scope="col">Status</th><th scope="col">Reported</th></tr></thead><tbody id="queue-rows">${tableRows()}</tbody></table></div><div class="table-foot" id="queue-count">${filtered().length} of ${state.incidents.length} incidents · Select an incident to review evidence and update status</div></section><aside class="side-stack"><section class="panel"><div class="panel-head"><h2>District signals</h2><span>↗</span></div><div class="alert-content">${alerts.length?alerts.map(a=>`<div class="alert-card"><span class="pill orange">Review suggested</span><strong style="margin-top:9px">${esc(a.district)} · ${esc(CATEGORIES[a.category])}</strong><p>${a.count} distinct unresolved incidents reported in the last 7 days.</p><button class="text-button" data-alert-category="${esc(a.category)}" data-alert-district="${esc(a.district)}">Review these incidents →</button></div>`).join(''):'<p>No groups currently meet the alert threshold.</p>'}<div class="alert-note">Demo rule: 3+ distinct open incidents of the same category in a district within 7 days. Supporting reports count once. Alerts stay on this dashboard; no elected official is contacted.</div></div></section><section class="panel"><div class="panel-head"><h2>Service coverage</h2><span>⌖</span></div><div class="alert-content"><div class="legend-row"><span>West service area</span><span class="pill gray">District A</span></div><div class="legend-row"><span>East service area</span><span class="pill gray">District B</span></div><p class="small muted" style="margin-top:14px">Fictional boundaries for testing. Production routing needs verified local service boundaries.</p><button class="text-button" data-view="routing" style="margin-top:8px">Explore routing →</button></div></section></aside></div><div style="margin-top:20px"><button class="text-button" data-action="reset">Reset sample workspace</button></div></section>`;}
function routing(){return `<section><div class="page-title"><div><span class="overline">BEHIND EVERY REPORT</span><h1>The right issue. The right desk.</h1><p>A deterministic location lookup, followed by category-based department matching.</p></div><span class="pill orange">Fictional demo boundaries</span></div><div class="routing-layout"><section class="panel"><div class="panel-head"><h2>Test a route</h2><span>⌖</span></div><div class="panel-body"><p>Try a sample location or enter coordinates. This lookup does not create a report.</p><div class="form-field"><label for="route-category">Issue category</label><select id="route-category">${Object.entries(CATEGORIES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="form-field"><label for="route-sample">Sample location</label><select id="route-sample">${LOCATIONS.map((l,n)=>`<option value="${n}">${l.name}</option>`).join('')}<option value="custom">Custom coordinates</option></select></div><div class="coords"><div><label for="route-lat">Latitude</label><input id="route-lat" type="number" step="any" value="${LOCATIONS[0].lat}"></div><div><label for="route-lng">Longitude</label><input id="route-lng" type="number" step="any" value="${LOCATIONS[0].lng}"></div></div><button class="primary block" data-action="lookup" style="margin-top:18px">Find responsible department →</button><div id="route-result" aria-live="polite">${routeCard(routeReport('water',LOCATIONS[0].lat,LOCATIONS[0].lng))}</div><div class="routing-fixture">Demo coverage: latitude 37.300–37.360; longitude −121.940–−121.850. Split at −121.895 into west and east areas. These rectangles do not represent official city, utility, or congressional boundaries.</div></div></section><section class="panel"><div class="panel-head"><h2>How a report finds its home</h2><span>↗</span></div><div class="panel-body"><div class="flow-step"><span class="step-number">01</span><div><h3>Validate the location</h3><p>Confirm latitude and longitude are valid. A sample location, browser GPS, or manually entered coordinates supplies the point.</p></div></div><div class="flow-step"><span class="step-number">02</span><div><h3>Match the service boundary</h3><p>A point-in-polygon check finds the demo service area and its demo district. Boundary points use the first match consistently.</p></div></div><div class="flow-step"><span class="step-number">03</span><div><h3>Match the department</h3><p>Water leaks go to Water Services, road damage to Public Works, and streetlights to Street Lighting. Other categories need review.</p></div></div><div class="flow-step"><span class="step-number">04</span><div><h3>Keep uncertain reports visible</h3><p>Outside coverage or without a category match, the incident enters the manual review queue. It is never silently dropped.</p></div></div><div class="routing-fixture">External agency submission, verified jurisdiction data, sign-in, shared cloud storage, and image recognition are future integrations. This prototype saves locally and makes no external submissions.</div></div></section></div></section>`;}
function render(){document.querySelectorAll('.topbar [data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});$('#app').innerHTML=view==='resident'?resident():view==='agency'?agency():routing();bind();}
function changeView(next){capture();cancelGps();view=next;location.hash=next;render();}
function setScreen(next){cancelGps();if(busy){toast('Wait for the photo to finish preparing.');return;}if(next==='new'&&screen!=='new'){draft=blank();step=1;}screen=next;render();}
function capture(){if($('#description'))draft.description=$('#description').value;if($('#lat')){draft.lat=$('#lat').value.trim()===''?null:Number($('#lat').value);draft.lng=$('#lng').value.trim()===''?null:Number($('#lng').value);}}
function next(){capture();cancelGps();if(step===1&&(!draft.category||!draft.description.trim()))return error('Choose a category and add a short description.');if(step===2&&!validCoordinates(draft.lat,draft.lng))return error('Select a sample location or enter valid latitude and longitude.');if(step<3){step++;render();}}
async function photo(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type))return error('Please select a JPEG, PNG, or WebP image.');if(file.size>10*1024*1024)return error('Please choose a photo smaller than 10 MB.');capture();busy=true;render();try{const bitmap=await createImageBitmap(file);const scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();draft.photo=canvas.toDataURL('image/jpeg',.75);busy=false;render();}catch{busy=false;render();error('This photo could not be opened. Try a JPEG or PNG.');}}
function bind(){
 document.querySelectorAll('#app [data-view]').forEach(b=>b.onclick=()=>changeView(b.dataset.view));
 document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{capture();setScreen(b.dataset.screen);});
 document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{capture();draft.category=b.dataset.category;draft.duplicate=null;render();});
 document.querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>{cancelGps();const l=LOCATIONS[+b.dataset.location];Object.assign(draft,{lat:l.lat,lng:l.lng,location:l.name,duplicate:null});render();});
 document.querySelectorAll('[name="duplicate"]').forEach(r=>r.onchange=()=>{draft.duplicate=r.value||null;const btn=$('[data-action="submit"]');btn.textContent=draft.duplicate?'Add supporting report ↗':'Submit demo report ↗';});
 document.querySelectorAll('[data-report-tab]').forEach(b=>b.onclick=()=>{reportTab=b.dataset.reportTab;render();});
 $('#photo-input')?.addEventListener('change',e=>photo(e.target.files[0]));
 for(const id of ['lat','lng'])$('#'+id)?.addEventListener('input',()=>{cancelGps();draft.location='Entered coordinates';draft.duplicate=null;updateGpsControls();});
 const search=$('#search');if(search)search.oninput=()=>{filters.search=search.value;updateTable();};
 $('#filter-agency')?.addEventListener('change',e=>{filters.agency=e.target.value;updateTable();});$('#filter-status')?.addEventListener('change',e=>{filters.status=e.target.value;updateTable();});
 document.querySelectorAll('[data-alert-category]').forEach(b=>b.onclick=()=>openCluster(b.dataset.alertCategory,b.dataset.alertDistrict));
 $('#route-sample')?.addEventListener('change',e=>{if(e.target.value==='custom')return;const l=LOCATIONS[+e.target.value];$('#route-lat').value=l.lat;$('#route-lng').value=l.lng;lookup();});
 for(const id of ['route-lat','route-lng'])$('#'+id)?.addEventListener('input',()=>{$('#route-sample').value='custom';$('#route-result').textContent='Coordinates changed. Select “Find responsible department” to update.';});
 $('#route-category')?.addEventListener('change',lookup);
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
}
function updateTable(){$('#queue-rows').innerHTML=tableRows();$('#queue-count').textContent=`${filtered().length} of ${state.incidents.length} incidents · Select an incident to review evidence and update status`;document.querySelectorAll('#queue-rows [data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));}
function lookup(){const lat=$('#route-lat').value.trim(),lng=$('#route-lng').value.trim();$('#route-result').innerHTML=routeCard(routeReport($('#route-category').value,lat===''?null:Number(lat),lng===''?null:Number(lng)));}
function action(name){
 if(name==='start')return setScreen('new');
 if(name==='next')return next();
 if(name==='back'){capture();cancelGps();if(step>1)step--;else screen='home';return render();}
 if(name==='remove-photo'){capture();draft.photo=null;return render();}
 if(name==='gps')return gps();
 if(name==='cancel-gps'){cancelGps();return updateGpsControls();}
 if(name==='lookup')return lookup();
 if(name==='submit'){
  if(busy)return;
  try{const result=createSubmission(state,draft,owner,draft.duplicate);if(!persist(result.state))return;successId=result.id;draft=blank();screen='success';render();}catch(e){error(e.message);}return;
 }
 if(name==='export'){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),notice:'Civic Relay demo data. Fictional routing. No external delivery.',...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='civic-relay-reports.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(name==='reset'){if(!confirm('Replace all reports and photos in this browser with the original sample workspace? Export first if you want to keep them.'))return;if(persist(makeSeed())){filters={search:'',agency:'all',status:'all'};screen='home';draft=blank();step=1;render();toast('Sample workspace restored.');}return;}
}
function gpsControls(){
 const pending=gpsFeedback.status==='pending';
 const failed=gpsFeedback.status==='error';
 return `<div id="gps-controls"><button class="secondary block" data-action="gps" ${pending?'disabled':''}>⌖ ${pending?'Finding your location…':failed?'Retry current location':'Use my current location'}</button><div id="gps-status" class="${failed?'error':'phone-hint'}" role="${failed?'alert':'status'}" aria-live="polite">${esc(gpsFeedback.message)}</div>${pending?'<button class="text-button" data-action="cancel-gps">Cancel location request</button>':''}${failed?'<p class="location-help">If this preview cannot show a location prompt, open the <a href="https://civic-relay-vinay-1019.animalargovindan.chatgpt.site" target="_blank" rel="noopener noreferrer">demo link ↗</a> in Safari or Chrome. On Mac, check System Settings → Privacy &amp; Security → Location Services for your browser.</p>':''}</div>`;
}
function updateGpsControls(){
 const el=$('#gps-controls');if(!el)return;
 el.outerHTML=gpsControls();
 $('[data-action="gps"]').onclick=gps;
 $('[data-action="cancel-gps"]')?.addEventListener('click',()=>{cancelGps();updateGpsControls();});
}
function cancelGps(){
 if(cancelGpsRequest){cancelGpsRequest();cancelGpsRequest=null;}
 gpsFeedback={status:'idle',message:''};
}
function gps(){
 if(gpsFeedback.status==='pending')return;
 capture();cancelGps();
 const targetDraft=draft;
 gpsFeedback={status:'pending',message:'Allow location in the permission prompt. This request stops after 15 seconds.'};
 updateGpsControls();
 cancelGpsRequest=requestLocation({
  onSuccess:position=>{
   cancelGpsRequest=null;
   if(draft!==targetDraft||view!=='resident'||screen!=='new'||step!==2)return;
   // Cancellation on coordinate edits, preset selection, or navigation prevents
   // late callbacks from replacing a location the resident has already chosen.
   draft.lat=Number(position.lat.toFixed(6));draft.lng=Number(position.lng.toFixed(6));
   draft.location='Current location';draft.duplicate=null;
   gpsFeedback={status:'success',message:`Location selected${position.accuracy===null?'':` (accuracy about ${Math.round(position.accuracy)} m)`}. Check the coordinates before continuing.`};
   render();
  },
  onError:failure=>{
   cancelGpsRequest=null;
   if(draft!==targetDraft||view!=='resident'||screen!=='new'||step!==2)return;
   gpsFeedback={status:'error',message:failure.message};
   updateGpsControls();
  }
 });
}
function openCluster(category,district){const ids=clusterAlerts(state.incidents).find(a=>a.category===category&&a.district===district)?.ids||[];$('#detail-content').innerHTML=`<div class="panel-head"><h2 id="detail-title">${esc(district)} · ${esc(CATEGORIES[category])}</h2><button class="dialog-close" aria-label="Close detail">×</button></div><div class="dialog-body"><p class="muted small">Distinct unresolved incidents from the last 7 days. No notification has been sent.</p>${state.incidents.filter(i=>ids.includes(i.id)).map(mini).join('')}</div>`;$('#detail-content .dialog-close').onclick=()=>$('#detail-dialog').close();$('#detail-content').querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function openDetail(id){const i=state.incidents.find(i=>i.id===id);if(!i)return;const canEdit=view==='agency';$('#detail-content').innerHTML=`<div class="panel-head"><span class="overline">${esc(i.id)} · ${esc(CATEGORIES[i.category])}</span><button class="dialog-close" aria-label="Close report">×</button></div><div class="dialog-body"><h2 id="detail-title">${esc(i.title)}</h2><div class="detail-meta">${statusBadge(i.status)}<br>Reported ${date(i.created)} · ${i.reports.length} supporting report${i.reports.length===1?'':'s'}<br>⌖ ${i.lat.toFixed(5)}, ${i.lng.toFixed(5)} · ${esc(i.location)}</div>${routeCard(i.route)}${canEdit?`<div class="actions-grid"><div><label for="status-update">Update demo status</label><select id="status-update">${STATUSES.map(s=>`<option ${s===i.status?'selected':''}>${s}</option>`).join('')}</select></div><button id="save-status" class="primary">Save update</button></div><label for="agency-note">Update note (optional)</label><textarea id="agency-note" maxlength="500" placeholder="For example: crew scheduled to inspect the issue." style="min-height:65px"></textarea>${!i.route.agency?`<div class="actions-grid"><div><label for="manual-agency">Assign department after review</label><select id="manual-agency"><option value="">Choose department</option>${Object.values(AGENCIES).map(a=>`<option>${esc(a)}</option>`).join('')}</select></div><button id="assign-agency" class="secondary">Assign</button></div>`:''}`:''}<h3 class="detail-section">Resident evidence</h3>${i.reports.map(r=>`<div class="evidence"><span class="small muted">${r.owner==='sample'?'Sample evidence':r.owner===owner?'Your report':'Supporting report'} · ${date(r.created)}</span>${r.photo?`<img src="${esc(r.photo)}" alt="Resident photo of the issue">`:''}<p>${esc(r.description)}</p></div>`).join('')}<h3 class="detail-section">Status history</h3><ol class="timeline">${[...i.history].reverse().map(h=>`<li><strong>${esc(h.status)}</strong><small>${date(h.at)}</small>${esc(h.note)}</li>`).join('')}</ol><p class="small muted">Demo updates are local to this browser. No external department is connected.</p></div>`;
 $('#detail-content .dialog-close').onclick=()=>$('#detail-dialog').close();
 $('#save-status')?.addEventListener('click',()=>{const next=structuredClone(state),item=next.incidents.find(n=>n.id===id);const status=$('#status-update').value,note=$('#agency-note').value.trim();if(status===item.status&&!note)return toast('Choose a new status or add a note.');item.status=status;item.updated=Date.now();item.history.push({status,at:item.updated,note:note||'Status updated in agency demo.'});if(persist(next)){render();openDetail(id);toast('Status saved. The resident view is up to date.');}});
 $('#assign-agency')?.addEventListener('click',()=>{const assigned=$('#manual-agency').value;if(!Object.values(AGENCIES).includes(assigned))return toast('Choose a department first.');const next=structuredClone(state),item=next.incidents.find(n=>n.id===id);item.route={...item.route,agency:assigned,reason:'Manually assigned in demo; service ownership still requires real-world verification.'};item.updated=Date.now();item.history.push({status:item.status,at:item.updated,note:'Manually assigned to '+assigned+'.'});if(persist(next)){render();openDetail(id);toast('Demo department assigned.');}});
 if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
}
// Cross-tab updates refresh local state. Concurrent edits are last-write-wins; production needs a shared backend.
window.addEventListener('storage',e=>{if(e.key!==STORE||!e.newValue)return;try{const data=JSON.parse(e.newValue);if(data.version!==1||!Array.isArray(data.incidents))return;state=data;if(!$('#detail-dialog').open&&screen!=='new')render();else toast('Reports changed in another tab. Review before saving.');}catch{toast('Could not load a change from another tab.');}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['resident','agency','routing'].includes(next)&&next!==view){capture();cancelGps();view=next;render();}});
document.querySelectorAll('.topbar [data-view]').forEach(b=>b.onclick=()=>changeView(b.dataset.view));
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog'))$('#detail-dialog').close();});
render();if(storageProblem)toast(storageProblem);
